/**
 * Verified food safety alerts. A recall needs a source link and a second team member's
 * approval. Nothing is scraped, inferred from scores, or generated by AI.
 *
 * Channels: in-app (everyone matched), Expo push (everyone with a token, free), SMS (only users
 * who opted in after seeing the BDT 2 per SMS disclosure and have a linked Banglalink number).
 */
import { and, eq, inArray } from "drizzle-orm";
import type { Db } from "./db/client";
import { alertSends, favorites, history, notifications, phoneLinks, profiles, pushTokens, recalls } from "./db/schema";
import { sendSms } from "./applink/client";
import { isEnabled } from "./applink/config";
import { adminIds } from "./env";

export class AlertError extends Error {}

export async function createRecall(
  db: Db,
  by: string,
  input: { title: string; body: string; shortText: string; sourceUrl: string; productIds: string[]; isTest: boolean },
) {
  if (!/^https:\/\//.test(input.sourceUrl)) throw new AlertError("A recall needs an https source link.");
  if (input.productIds.length === 0) throw new AlertError("Pick at least one affected product.");
  const shortText = input.shortText.normalize("NFKD").replace(/[^\x20-\x7e]/g, "").slice(0, 140);
  const [row] = await db.insert(recalls).values({ ...input, shortText, createdBy: by }).returning();
  return row;
}

/** Second-person approval, then fan-out. Returns how many users each channel reached. */
export async function approveRecall(db: Db, recallId: number, approver: string) {
  const [r] = await db.select().from(recalls).where(eq(recalls.id, recallId));
  if (!r) throw new AlertError("Recall not found.");
  if (r.status !== "draft") throw new AlertError("Only a draft can be approved.");
  if (r.createdBy === approver) throw new AlertError("A different team member must approve this recall.");
  await db.update(recalls).set({ status: "approved", approvedBy: approver, approvedAt: new Date() }).where(eq(recalls.id, recallId));
  return fanOut(db, { ...r, approvedBy: approver });
}

async function affectedUsers(db: Db, productIds: string[], isTest: boolean): Promise<string[]> {
  const fromHistory = await db.selectDistinct({ userId: history.userId }).from(history).where(inArray(history.productId, productIds));
  const fromFav = await db.selectDistinct({ userId: favorites.userId }).from(favorites).where(inArray(favorites.productId, productIds));
  let ids = [...new Set([...fromHistory, ...fromFav].map((r) => r.userId))];
  // A TEST recall only ever reaches team members.
  if (isTest) ids = ids.filter((id) => adminIds.has(id));
  return ids;
}

async function fanOut(db: Db, r: typeof recalls.$inferSelect) {
  const users = await affectedUsers(db, r.productIds, r.isTest);
  const title = r.isTest ? `[TEST] ${r.title}` : r.title;
  let inapp = 0;
  let push = 0;
  let sms = 0;

  for (const userId of users) {
    const claimed = await db
      .insert(alertSends)
      .values({ recallId: r.id, userId, channel: "inapp", status: "sent" })
      .onConflictDoNothing()
      .returning();
    if (claimed.length === 0) continue; // already alerted
    await db.insert(notifications).values({ userId, kind: "recall", title, body: r.body, data: { recallId: r.id, productIds: r.productIds, sourceUrl: r.sourceUrl } });
    inapp++;
  }

  const tokens = users.length ? await db.select().from(pushTokens).where(inArray(pushTokens.userId, users)) : [];
  if (tokens.length) {
    push = await sendExpoPush(
      tokens.map((t) => t.token),
      title,
      r.shortText,
      { recallId: r.id },
    );
  }

  if (isEnabled("smsSend") && users.length) {
    const optedIn = await db
      .select({ userId: profiles.userId, subscriberId: phoneLinks.subscriberId })
      .from(profiles)
      .innerJoin(phoneLinks, eq(phoneLinks.userId, profiles.userId))
      .where(and(inArray(profiles.userId, users), eq(profiles.smsAlertsOptIn, true)));
    for (const u of optedIn) {
      const [row] = await db
        .insert(alertSends)
        .values({ recallId: r.id, userId: u.userId, channel: "sms", status: "queued" })
        .onConflictDoNothing()
        .returning();
      if (!row) continue;
      try {
        const text = `NutriScan ${r.isTest ? "TEST " : ""}alert: ${r.shortText} Reply STOP to end alerts.`.slice(0, 160);
        const res = await sendSms(u.subscriberId, text, { deliveryStatusRequest: "1" });
        await db.update(alertSends).set({ status: "sent", requestId: res.requestId ?? null, updatedAt: new Date() }).where(eq(alertSends.id, row.id));
        sms++;
      } catch {
        // One failure is recorded and not retried in a loop: every SMS costs the user money.
        await db.update(alertSends).set({ status: "failed", updatedAt: new Date() }).where(eq(alertSends.id, row.id));
      }
    }
  }
  return { users: users.length, inapp, push, sms };
}

export async function sendExpoPush(tokens: string[], title: string, body: string, data: Record<string, unknown>): Promise<number> {
  const valid = tokens.filter((t) => /^ExponentPushToken\[.+\]$/.test(t));
  let sent = 0;
  for (let i = 0; i < valid.length; i += 100) {
    const batch = valid.slice(i, i + 100).map((to) => ({ to, title, body, data, sound: "default" }));
    try {
      const res = await fetch("https://exp.host/--/api/v2/push/send", {
        method: "POST",
        headers: { "content-type": "application/json", accept: "application/json" },
        body: JSON.stringify(batch),
        signal: AbortSignal.timeout(10_000),
      });
      if (res.ok) sent += batch.length;
    } catch {
      // Push is best effort; the in-app notification is the record.
    }
  }
  return sent;
}

const SMPP_SPELLINGS: Record<string, string> = { DELIVRD: "DELIVERED", UNDELIV: "UNDELIVERABLE", ACCEPTD: "ACCEPTED", REJECTD: "REJECTED" };

export async function applyDeliveryReport(db: Db, n: { requestId?: string; deliveryStatus?: string }) {
  if (!n.requestId || !n.deliveryStatus) return "ignored";
  const status = SMPP_SPELLINGS[n.deliveryStatus] ?? n.deliveryStatus;
  await db.update(alertSends).set({ status, updatedAt: new Date() }).where(eq(alertSends.requestId, n.requestId));
  return "applied";
}

/** MO SMS: STOP turns alerts off for the sender. Nothing chargeable ever happens from an SMS. */
export async function applyIncomingSms(db: Db, n: { sourceAddress?: string; message?: string }) {
  if (!n.sourceAddress || typeof n.message !== "string") return "ignored";
  const words = n.message.trim().toUpperCase().split(/\s+/);
  if (!words.some((w) => w === "STOP" || w === "UNSUB")) return "ignored";
  const [link] = await db.select().from(phoneLinks).where(eq(phoneLinks.subscriberId, n.sourceAddress));
  if (!link) return "ignored";
  await db.update(profiles).set({ smsAlertsOptIn: false, updatedAt: new Date() }).where(eq(profiles.userId, link.userId));
  return "stopped";
}
